cd /workspace && python3 - <<'EOF'
import sys, json
print('limit', sys.get_int_max_str_digits())
tests = ['0.'+'0'*5000+'1', '9'*5000, '9'*5000+'.0', '1e5000', '1e-5000', '-'+'9'*4301, '1'+'0'*4300]
for t in tests:
    try:
        v=float(t); print('float ok %-14s -> %r'%(t[:12]+'..', v))
    except Exception as e: print('float ERR %-14s -> %s'%(t[:12]+'..', e))
    try:
        v=int(t); print('   int ok -> %d digits'%(len(str(v))))
    except Exception as e: print('   int ERR ->', str(e)[:60])
# does json use parse_float for these?
for t in tests:
    try:
        r=json.loads('{"a":%s}'%t, parse_float=lambda s:('F',float(s)), parse_int=lambda s:('I',int(s)))
        print('json %-14s -> %r'%(t[:12]+'..', r['a'][0], ))
    except Exception as e: print('json %-14s ERR %s'%(t[:12]+'..', str(e)[:60]))
# set limit and retest float
sys.set_int_max_str_digits(4300)
try: print('after set:', float('9'*5000))
except Exception as e: print('after set ERR', e)
EOF
